// Renders the marketing site's social card (site/assets/og-image.png, 1200×630).
// Run: ./node_modules/.bin/electron scripts/make-og-image.cjs
const { app, BrowserWindow } = require('electron')
const { readFileSync, writeFileSync } = require('fs')
const { join } = require('path')

const ROOT = join(__dirname, '..')
const W = 1200
const H = 630

// The app icon's mark (generated by scripts/make-icon.cjs) on the left.
const mark = readFileSync(join(ROOT, 'build', 'icon.svg'), 'utf8').replace('<svg ', '<svg class="mark" ')

const hues = Array.from({ length: 12 }, (_, i) => i * 30)
const spectrum = `linear-gradient(90deg, ${hues.map((h, i) => `hsl(${h} 80% 60%) ${((i / 11) * 100).toFixed(1)}%`).join(', ')})`

const html = `<!doctype html><html><head><meta charset="utf-8"><style>
html,body{margin:0;padding:0;overflow:hidden}
body{width:${W}px;height:${H}px;background:radial-gradient(900px 600px at 78% -10%, #1c1c2c 0%, #0b0b11 55%, #07070a 100%);
  font-family:-apple-system,BlinkMacSystemFont,'Inter','SF Pro Display',system-ui,sans-serif;color:#e7e7ef;position:relative}
.mark{position:absolute;left:84px;top:115px;width:400px;height:400px;filter:drop-shadow(0 30px 60px rgba(0,0,0,.55))}
.copy{position:absolute;left:548px;top:150px;right:70px}
.word{font-size:30px;font-weight:800;letter-spacing:.2em}
.word span{color:rgba(255,255,255,.45);font-weight:650}
h1{margin:26px 0 0;font-size:62px;line-height:1.04;font-weight:750;letter-spacing:-.02em}
p{margin:22px 0 0;font-size:24px;line-height:1.45;color:rgba(255,255,255,.62)}
.bar{position:absolute;left:0;right:0;bottom:0;height:8px;background:${spectrum};opacity:.9}
.chips{display:flex;gap:12px;margin-top:30px}
.chip{font:600 18px ui-monospace,'SF Mono',Menlo,monospace;padding:8px 14px;border-radius:10px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.8)}
</style></head><body>
${mark}
<div class="copy">
  <div class="word">VIBE <span>DETECTOR</span></div>
  <h1>Detect the vibe of every sound.</h1>
  <p>Key and BPM for every sample, read from the audio itself — loops locked to their exact bar grid. On your machine.</p>
  <div class="chips"><span class="chip">A minor · 8A</span><span class="chip">92 BPM</span><span class="chip">Drum loop</span></div>
</div>
<div class="bar"></div>
</body></html>`

app.whenReady().then(async () => {
  const win = new BrowserWindow({ width: W, height: H, show: false, useContentSize: true, frame: false })
  await win.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(html))
  await new Promise((r) => setTimeout(r, 500))
  const img = await win.webContents.capturePage()
  const out = join(ROOT, 'site', 'assets', 'og-image.png')
  writeFileSync(out, img.resize({ width: W, height: H }).toPNG())
  console.log('og image →', out)
  app.quit()
})
